// ─── Neural network forward pass ────────────────────────────────────────────

const relu = (x) => x.map(v => Math.max(0, v));

const softmax = (x) => {
  const max = Math.max(...x);
  const exp = x.map(v => Math.exp(v - max));
  const sum = exp.reduce((a, b) => a + b, 0);
  return exp.map(v => v / sum);
};

const matmul = (vec, matrix, bias) => {
  const out = new Array(matrix[0].length).fill(0);
  for (let j = 0; j < matrix[0].length; j++) {
    let sum = bias[j];
    for (let i = 0; i < vec.length; i++) {
      sum += vec[i] * matrix[i][j];
    }
    out[j] = sum;
  }
  return out;
};

const predict = (features) => {
  const z1 = matmul(features, W1, b1);
  const a1 = relu(z1);
  const z2 = matmul(a1, W2, b2);
  const a2 = relu(z2);
  const z3 = matmul(a2, W3, b3);
  const probs = softmax(z3);

  let bestIdx = 0;
  let bestProb = 0;
  const allProbs = {};
  for (let i = 0; i < CARD_TYPES.length; i++) {
    allProbs[CARD_TYPES[i]] = probs[i];
    if (probs[i] > bestProb) {
      bestProb = probs[i];
      bestIdx = i;
    }
  }

  return {
    cardType: CARD_TYPES[bestIdx],
    confidence: bestProb,
    allProbs,
  };
};

// ─── Context helpers ────────────────────────────────────────────────────────

const getMinsSinceLastTap = async (category) => {
  try {
    const raw = await AsyncStorage.getItem('unapp_patterns');
    if (!raw) return 1440;
    const patterns = JSON.parse(raw);
    const match = patterns.find(p => p.type === category);
    if (!match || !match.lastQueried) return 1440;
    const minsAgo = (Date.now() - new Date(match.lastQueried).getTime()) / 60000;
    return Math.min(Math.round(minsAgo), 1440);
  } catch {
    return 1440;
  }
};

const getUsagePhase = async () => {
  try {
    const opens = await AsyncStorage.getItem('unapp_opens');
    const count = parseInt(opens || '0', 10);
    if (count > 42) return 'hot';
    if (count > 14) return 'warm';
    return 'cold';
  } catch {
    return 'cold';
  }
};

// ─── Main prediction function ───────────────────────────────────────────────

export const getCoreMLPrediction = async () => {
  try {
    const now = new Date();
    const h = now.getHours();
    const m = now.getMinutes();
    const d = now.getDay();
    const wk = (d === 0 || d === 6) ? 1 : 0;

    const [minsCab, minsFood, minsStocks] = await Promise.all([
      getMinsSinceLastTap('cab'),
      getMinsSinceLastTap('food'),
      getMinsSinceLastTap('stocks'),
    ]);

    const phase = await getUsagePhase();
    const threshold = THRESHOLDS[phase] || THRESHOLDS.cold;

    // Normalize to 0-1 (must match training normalization)
    const features = [
      h / 23,           // hour
      m / 59,           // minute
      d / 6,            // day_of_week
      wk,               // is_weekend
      0,                // is_holiday
      0,                // location_cluster (TODO)
      0.5,              // battery_level (TODO)
      0,                // is_charging (TODO)
      0,                // has_event_within_60min (TODO)
      0,                // event_has_location (TODO)
      minsCab / 1440,   // mins_since_last_cab
      minsFood / 1440,  // mins_since_last_food
      minsStocks / 1440,// mins_since_last_stocks
    ];

    const result = predict(features);

    console.log(`[un-app] Prediction: ${result.cardType} (${(result.confidence * 100).toFixed(1)}%) phase=${phase}`);

    return {
      cardType: result.cardType,
      confidence: result.confidence,
      shouldShow: result.confidence >= threshold && result.cardType !== 'nothing',
      allProbs: result.allProbs,
      source: 'js-neural-net',
    };
  } catch (e) {
    console.log('[un-app] Prediction error:', e.message);
    return { cardType: 'nothing', confidence: 0, shouldShow: false, source: 'fallback' };
  }
};
